    // Helper builder method to make explicit instantiation clean and safe
    private CloudMetricEntity create(
            String evId, String isoTs, CompanyInfoEntity co, String agId, String ip,
            double cpu, int cores, double memP, long totM, long usdM, long frM,
            double nIn, double nOut, double stGb, double dP, int qps, double qMs,
            double cHit, int rpm, double err, double resp) {
        
        CloudMetricEntity e = new CloudMetricEntity();
        e.setEventId(evId);
        e.setLocalDateTime(Instant.parse(isoTs));
        e.setCompanyInfoEntity(co);
        e.setAgentInfoEntity(new AgentInfoEntity(agId, agId + ".internal", ip));
        e.setComputeInfoEntity(new ComputeInfoEntity(cpu, cores, cpu/10.0, cpu/12.0, cpu/15.0));
        e.setMemoryInfoEntity(new MemoryInfoEntity(totM, usdM, frM, memP));
        e.setNetworkInfoEntity(new NetworkInfoEntity(nIn, nOut, (int)(nIn * 0.4)));
        e.setDiskInfoEntity(new DiskInfoEntity(cpu * 2.1, cpu * 1.3, dP, stGb));
        e.setDatabaseInfoEntity(new DatabaseInfoEntity(qps / 8, qps, qMs, cHit, stGb * 0.4));
        e.setApplicationInfoEntity(new ApplicationInfoEntity(rpm, err, resp));
        e.setResourceInfoEntity(new ResourceInfoEntity("EC2", "res-" + evId, "PRODUCTION", "ap-south-1", "ap-south-1a"));
        return e;
    }
